# %% ../nbs/09_train_dec.ipynb #f0cf8a0f
def setup_dataloaders(cfg, preencoded=False):
    nw = cfg.training.get('num_workers', [6, 4])
    batch_size = cfg.training.dec_batch_size
    if preencoded:
        encoded_dir = cfg.preencode.output_dir
        train_ds = PreEncodedChunkDataset(encoded_dir, split='train')
        val_ds   = PreEncodedChunkDataset(encoded_dir, split='val')
        train_dl = DataLoader(train_ds, batch_size=batch_size,
                              sampler=ChunkShuffleSampler(train_ds, shuffle=True),
                              num_workers=nw[0], persistent_workers=(nw[0]>0),
                              collate_fn=collate_preencode)
        val_dl   = DataLoader(val_ds, batch_size=batch_size,
                              sampler=ChunkShuffleSampler(val_ds, shuffle=False),
                              num_workers=nw[1], persistent_workers=(nw[1]>0),
                              collate_fn=collate_preencode)
    elif cfg.data.get('format', 'png') == 'sharded':
        train_ds = ShardedAnchorDataset(cfg.data.path, split='train', aug_y_max=cfg.training.max_shift_y)
        val_ds   = ShardedAnchorDataset(cfg.data.path, split='val',  aug_y_max=cfg.training.max_shift_y)
        train_dl = DataLoader(train_ds, batch_size=batch_size, sampler=ChunkShuffleSampler(train_ds, shuffle=True),
                               num_workers=nw[0], pin_memory=True, drop_last=True, persistent_workers=(nw[0] > 0))
        val_dl   = DataLoader(val_ds,   batch_size=batch_size, sampler=ChunkShuffleSampler(val_ds, shuffle=False),
                               num_workers=nw[1], pin_memory=True, drop_last=True, persistent_workers=(nw[1] > 0))
    else:
        train_ds = AnchorDataset(image_dataset_dir=cfg.data.path, split='train', aug_y_max=cfg.training.max_shift_y)
        val_ds   = AnchorDataset(image_dataset_dir=cfg.data.path, split='val',  aug_y_max=cfg.training.max_shift_y)
        train_dl = DataLoader(train_ds, batch_size=batch_size, shuffle=True,  num_workers=nw[0], pin_memory=True, drop_last=True)
        val_dl   = DataLoader(val_ds,   batch_size=batch_size, shuffle=False, num_workers=nw[1], pin_memory=True, drop_last=True)
    return train_dl, val_dl


# %% ../nbs/09_train_dec.ipynb #b221cde1
def setup_models(cfg, device, preencoded, verbose=True): 
    encoder = None
    if not preencoded:
        if cfg.model.get('encoder', 'vit') == 'swin':
            encoder = SwinEncoder(img_height=cfg.data.image_size, img_width=cfg.data.image_size,
                            patch_h=cfg.model.patch_h, patch_w=cfg.model.patch_w,
                            embed_dim=cfg.model.embed_dim, depths=cfg.model.depths,
                            num_heads=cfg.model.num_heads, window_size=cfg.model.window_size,
                            mlp_ratio=cfg.model.mlp_ratio, drop_path_rate=cfg.model.drop_path_rate).to(device)
        else:
            encoder = ViTEncoder(cfg.data.in_channels, cfg.data.image_size, cfg.model.patch_size,
                                 cfg.model.dim, cfg.model.depth, cfg.model.heads).to(device)
            
        encoder = load_checkpoint(encoder, cfg.get('encoder_ckpt', f'checkpoints/{encoder.__class__.__name__}__best.pt'))
        if cfg.training.get('enc_ft_lr', 0) <=0: 
            cjprint("Freezing Encoder ❄️ ❄️ ❄️",color='blue')
            encoder.eval()  # frozen
            for p in encoder.parameters(): p.requires_grad = False
        else: 
            cjprint("Encoder is hot 🔥🔥🔥, will train",color='red') 
            encoder.train()

    if cfg.model.get('encoder', 'vit') == 'swin': # decoder should match encoder
        decoder = SwinDecoder(img_height=cfg.data.image_size, img_width=cfg.data.image_size,
                            patch_h=cfg.model.patch_h, patch_w=cfg.model.patch_w,
                            embed_dim=cfg.model.embed_dim,
                            depths=cfg.model.get('dec_depths', cfg.model.depths), 
                            num_heads=cfg.model.get('dec_num_heads', cfg.model.num_heads)).to(device)
    else: 
        decoder = ViTDecoder(cfg.data.in_channels, (cfg.data.image_size, cfg.data.image_size),
                         cfg.model.patch_size, cfg.model.dim, 
                         cfg.model.get('dec_depth', 4), cfg.model.get('dec_heads', 8)).to(device)


    #encoder = torch.compile(encoder)  # takes too long, doesn't speed up much
    #decoder = torch.compile(decoder)
    if verbose:
        cjprint("\n** Models:",encoder.__class__.__name__, decoder.__class__.__name__, color="cyan")
        cjprint(f"Decoder Total, Trainable: {', '.join(f'{x:,}' for x in param_count(decoder))}", color="cyan")
    
    return encoder, decoder 

# %% ../nbs/09_train_dec.ipynb #61dd1ef1
def setup_tstate(cfg, device, decoder, encoder=None, extra_params=None):
    "Training_state: Losses, Optimizers, Schedulers, AMP Scalers"
    opt_enc = None #if encoder is None else torch.optim.AdamW(encoder.parameters(), lr=cfg.training.enc_ft_lr)
    dec_params = list(decoder.parameters()) + (extra_params or [])
    opt_dec = torch.optim.AdamW(dec_params, lr=cfg.training.dec_lr)
    scheduler = torch.optim.lr_scheduler.OneCycleLR(opt_dec, max_lr=cfg.training.dec_lr, steps_per_epoch=1, epochs=cfg.training.dec_epochs, div_factor=4)
    scheduler_enc = None if opt_enc is None else torch.optim.lr_scheduler.OneCycleLR(opt_enc, max_lr=cfg.training.enc_ft_lr, steps_per_epoch=1, epochs=max(1, cfg.training.dec_epochs))   
    scaler_dec = torch.amp.GradScaler()
    TrainState = namedtuple('TrainState', ['opt_enc', 'opt_dec',  'scaler_dec','scheduler','scheduler_enc'])
    return TrainState(opt_enc, opt_dec, scaler_dec, scheduler, scheduler_enc)

# %% ../nbs/09_train_dec.ipynb #102f0438
def get_embeddings_batch(batch, encoder, device='cuda', allow_grad=False):
    "Encode a raw image batch; returns (enc_out, img, note_weights)."
    img = batch['img'].to(device)
    note_weights = batch['note_weights'].to(device) if 'note_weights' in batch else None
    with (nullcontext() if allow_grad else torch.no_grad()), torch.autocast(device_type='cuda', dtype=torch.bfloat16):
        enc_out = encoder(img)
    return enc_out, img, note_weights


# %% ../nbs/09_train_dec.ipynb #928a8d39
def train_step(epoch, enc_out, img_real, decoder,
            tstate,  # named tuple containing optimizers, loss fns, scalers
            cfg,    # config
            note_weights=None,
            mask_tokens=None,
            ):
    "training step for decoder"
    decoder.train()
    tstate.opt_dec.zero_grad()
    enc_out = mask_enc_out(enc_out,
                           mask_ratio=cfg.training.get('emb_mask_ratio', 0.0),
                           mr_level_fac=cfg.training.get('emb_mask_level_fac', 1.25),
                           zero_levels=cfg.training.get('zero_levels', None),
                           mask_tokens=mask_tokens)
    with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
        loss_dict = calc_dec_loss(decoder, enc_out, img_real, pos_weight=cfg.training.get('pos_weight',1.0), note_weights=note_weights)
    tstate.scaler_dec.scale(loss_dict['dec']).backward()
    tstate.scaler_dec.unscale_(tstate.opt_dec)
    torch.nn.utils.clip_grad_norm_(decoder.parameters(), max_norm=1.0)
    tstate.scaler_dec.step(tstate.opt_dec)
    tstate.scaler_dec.update()
    return loss_dict, loss_dict['recon']

